 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    groups = {}
    for color in colors:
        seen = set()
        comps = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                minr = min(y for y,x in cells); maxr = max(y for y,x in cells)
                minc = min(x for y,x in cells); maxc = max(x for y,x in cells)
                shape = {(y-minr,x-minc) for y,x in cells}
                comps.append((len(cells), maxr-minr+1, maxc-minc+1, shape))
        groups[color] = comps
    ordered = sorted(colors, key=lambda col: sum(x[0] for x in groups[col]))
    out = [[0]*w for _ in range(h)]
    x0 = 0
    for color in ordered:
        comps = sorted(groups[color], key=lambda x: x[0])
        total_height = sum(comp[1] for comp in comps) + max(0, len(comps)-1)
        y0 = h - total_height
        for size, ch, cw, shape in comps:
            for dy, dx in shape:
                y, x = y0+dy, x0+dx
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
            y0 += ch + 1
        x0 += max(comp[2] for comp in groups[color]) + 1
    return out
